message:
Running command: cd /workspace/repo-vul/src-vul/htslib && cat > /tmp/driver.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);
int main(int argc, char **argv) {
    if (argc < 2) return 1;
    FILE *f = fopen(argv[1], "rb");
    if (!f) return 1;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *buf = malloc(sz ? sz : 1);
    fread(buf, 1, sz, f);
    fclose(f);
    LLVMFuzzerTestOneInput(buf, sz);
    free(buf);
    return 0;
}
EOF
export AFL_PATH=/workspace/repo-vul/src-vul/afl
$AFL_PATH/afl-gcc -g -O1 -fsanitize=address -fno-omit-frame-pointer -I. -o /tmp/hts_fuzzer_afl /tmp/driver.c test/fuzz/hts_open_fuzzer.o libhts.a -lz -lbz2 -llzma -lcrypto -lpthread -ldeflate -lm 2>&1 | tail -5
echo "build done"; ls -la /tmp/hts_fuzzer_afl

